package run.ikaros.planning; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono;
@RestController @RequestMapping("/api/v2/planning/projects/{projectId}/sections") public class PlanningProjectSectionController {private final PlanningProjectSectionService s;public PlanningProjectSectionController(PlanningProjectSectionService s){this.s=s;}@PostMapping public Mono<PlanningProjectSectionView> create(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID projectId,@Valid@RequestBody CreatePlanningProjectSectionRequest r){return s.create(o,projectId,r);}@GetMapping public Flux<PlanningProjectSectionView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID projectId){return s.list(o,projectId);}@PatchMapping("/{sectionId}")public Mono<PlanningProjectSectionView> update(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID sectionId,@Valid@RequestBody UpdatePlanningProjectSectionRequest r){return s.update(o,sectionId,r);}@DeleteMapping("/{sectionId}")public Mono<Void> delete(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID sectionId){return s.delete(o,sectionId);}}
